import{_ as s,C as n,o as r,c as i,j as t,a as o,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse('{"title":"Run environment","description":"Where each run executed (the runner, each browser, each server under test) and what changed between two runs, two shards, or a failure and its last pass.","frontmatter":{"title":"Run environment","description":"Where each run executed (the runner, each browser, each server under test) and what changed between two runs, two shards, or a failure and its last pass.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-environment.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-environment.html"}],["meta",{"property":"og:title","content":"Run environment | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Where each run executed (the runner, each browser, each server under test) and what changed between two runs, two shards, or a failure and its last pass."}]]},"headers":[],"relativePath":"features/run-environment.md","filePath":"features/run-environment.md","lastUpdated":1794177867000}'),d={name:"features/run-environment.md"};function c(p,e,u,g,m,k){const a=n("Needs");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"run-environment",tabindex:"-1"},[o("Run environment "),t("a",{class:"header-anchor",href:"#run-environment","aria-label":'Permalink to "Run environment"'},"​")],-1)),h(a,{reporter:""}),e[1]||(e[1]=l('<p>Piwi records where each run executed, so &quot;it fails on CI but not on my machine&quot; and &quot;it broke when the runner image changed&quot; become facts the dashboard shows. The reporter records three kinds of snapshot, each a closed list of fields: no environment variable is copied whole.</p><table tabindex="0"><thead><tr><th>Snapshot</th><th>One per</th><th>Fields</th></tr></thead><tbody><tr><td><strong>Runner</strong></td><td>shard</td><td>time zone, <code>TZ</code>, locale, <code>LANG</code> / <code>LC_ALL</code> / <code>LC_TIME</code>, OS and distribution, architecture, Node.js and ICU versions, CI runner image, container; host name, CPU and memory</td></tr><tr><td><strong>Browser</strong></td><td>shard and project</td><td>browser version, time zone, locale, languages, how it formats a number and a date, color scheme and reduced motion, headless; screen and user agent</td></tr><tr><td><strong>Server</strong></td><td>instrumented origin</td><td>runtime, OS, time zone, culture, globalization mode, environment name, app version; host name, process, start time, clock offset from the runner</td></tr></tbody></table><p>The browser snapshot needs the <a href="/guide/capture-fixtures.html">capture fixtures</a>: it is read from the test&#39;s page before the test navigates. The server snapshot needs an <a href="/guide/backend-logs.html#server-environment">instrumentation package</a>. The last fields of each row (after the semicolon) change by nature between runs and are never shown as a possible cause. <code>collectEnvironmentInfo: false</code> in the reporter options, or <code>PIWI_COLLECT_ENVIRONMENT_INFO=false</code>, turns it all off.</p><h2 id="where-it-shows" tabindex="-1">Where it shows <a class="header-anchor" href="#where-it-shows" aria-label="Permalink to &quot;Where it shows&quot;">​</a></h2><ul><li><strong>Run page</strong>: the <strong>Environment</strong> line under the versions opens every snapshot, shard by shard. It warns when the shards disagree (two runner images, two time zones), when a server restarted during the run, and when a server&#39;s clock is more than 2 s off the runner&#39;s, enough to break token expiry and &quot;created just now&quot; checks.</li><li><strong>Changes tab</strong>: the runner, browser and server fields that changed against the baseline run, grouped, with every value of a field the shards disagree on.</li><li><strong>Test page</strong>: the environment diff of the <strong>State</strong> tab, against the test&#39;s last pass. A browser time zone or locale the page did not report is <em>inferred</em> from the declared value, else the runner&#39;s, and labeled so.</li><li><strong>Trend charts</strong>: an automatic marker on the run where the runner, a browser or a server changed, against the previous run on the same branch and environment label.</li><li><strong>Flakiness tab</strong>: the runner&#39;s time zone and locale become <a href="/features/flake-lab.html">flake suspects</a> when the failures share one and the passes another; the <a href="/features/flake-lab.html">Flake Lab</a> runs the browser in it to confirm. The runner image and the browser version are listed as context.</li><li><strong>MCP</strong>: <code>get_run</code> returns the run&#39;s <code>environments</code>.</li></ul><p>A run from an older reporter, or with collection off, shows nothing: it was never recorded, and is never read as a change. Host names are left out of exports and share links.</p><h2 id="fails-on-ci-passes-locally" tabindex="-1">Fails on CI, passes locally <a class="header-anchor" href="#fails-on-ci-passes-locally" aria-label="Permalink to &quot;Fails on CI, passes locally&quot;">​</a></h2><p>A CI runner usually runs in <code>UTC</code> with <code>en-US</code>, a laptop in its own time zone and language, and a browser takes both from the machine unless the config sets <code>use.timezoneId</code> and <code>use.locale</code>. To reproduce a CI failure locally, run with CI&#39;s values:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-Np3d4" id="tab-LONStJ5" checked><label data-title="bash" for="tab-LONStJ5">bash</label><input type="radio" name="group-Np3d4" id="tab-7X4yAe6"><label data-title="PowerShell" for="tab-7X4yAe6">PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TZ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">UTC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">en_US.UTF-8</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TZ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en_US.UTF-8&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; npx playwright test</span></span></code></pre></div></div></div><p>Browsers on Windows may not follow <code>TZ</code>: set <code>use.timezoneId</code> in the Playwright config instead.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a>: the State tab and the rest of a failure&#39;s evidence.</li><li><a href="/guide/backend-logs.html#server-environment">Backend logs</a>: what a server under test answers.</li><li><a href="./flake-lab.html">Flake Lab</a>: confirm a time zone or locale suspect by experiment.</li><li><a href="/guide/ci.html">CI &amp; sharding</a>: the run metadata the reporter collects.</li></ul>',12))])}const v=s(d,[["render",c]]);export{b as __pageData,v as default};
